CREATE TYPE "AdmissionEnquiryStatus" AS ENUM ('NEW', 'CONTACTED', 'QUALIFIED', 'CLOSED', 'CONVERTED');
CREATE TYPE "AdmissionApplicationStatus" AS ENUM ('DRAFT', 'SUBMITTED', 'UNDER_REVIEW', 'DOCUMENTS_PENDING', 'APPROVED', 'OFFERED', 'ACCEPTED', 'REJECTED', 'WITHDRAWN', 'CONVERTED');
CREATE TYPE "AdmissionDocumentStatus" AS ENUM ('PENDING', 'RECEIVED', 'VERIFIED', 'REJECTED');
CREATE TYPE "AdmissionOfferStatus" AS ENUM ('DRAFT', 'OFFERED', 'ACCEPTED', 'DECLINED', 'EXPIRED', 'WITHDRAWN');
CREATE TABLE "AdmissionEnquiry" ( "id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"schoolId" TEXT NOT NULL,"childFirstName" TEXT NOT NULL,"childLastName" TEXT,"guardianName" TEXT NOT NULL,"guardianEmail" TEXT,"guardianPhone" TEXT NOT NULL,"desiredAcademicYearId" TEXT,"desiredGradeLevelId" TEXT,"source" TEXT,"notes" TEXT,"status" "AdmissionEnquiryStatus" NOT NULL DEFAULT 'NEW',"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AdmissionApplication" ( "id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"schoolId" TEXT NOT NULL,"applicationNumber" TEXT NOT NULL,"academicYearId" TEXT NOT NULL,"gradeLevelId" TEXT NOT NULL,"childFirstName" TEXT NOT NULL,"childMiddleName" TEXT,"childLastName" TEXT,"dateOfBirth" DATE,"gender" TEXT,"guardianName" TEXT NOT NULL,"guardianRelationship" TEXT,"guardianEmail" TEXT,"guardianPhone" TEXT NOT NULL,"address" JSONB,"status" "AdmissionApplicationStatus" NOT NULL DEFAULT 'DRAFT',"submittedAt" TIMESTAMP(3),"reviewedBy" TEXT,"reviewedAt" TIMESTAMP(3),"reviewNotes" TEXT,"convertedStudentId" TEXT UNIQUE,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AdmissionApplicationDocument" ( "id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"schoolId" TEXT NOT NULL,"applicationId" TEXT NOT NULL,"documentType" TEXT NOT NULL,"displayName" TEXT NOT NULL,"objectKey" TEXT NOT NULL,"mimeType" TEXT,"sizeBytes" BIGINT,"isRequired" BOOLEAN NOT NULL DEFAULT TRUE,"status" "AdmissionDocumentStatus" NOT NULL DEFAULT 'PENDING',"reviewNotes" TEXT,"reviewedBy" TEXT,"reviewedAt" TIMESTAMP(3),"uploadedBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AdmissionStageHistory" ( "id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"schoolId" TEXT NOT NULL,"applicationId" TEXT NOT NULL,"fromStatus" "AdmissionApplicationStatus","toStatus" "AdmissionApplicationStatus" NOT NULL,"actorUserId" TEXT NOT NULL,"note" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AdmissionOffer" ( "id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"schoolId" TEXT NOT NULL,"applicationId" TEXT NOT NULL,"offerNumber" TEXT NOT NULL,"status" "AdmissionOfferStatus" NOT NULL DEFAULT 'DRAFT',"offeredAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3),"acceptedAt" TIMESTAMP(3),"feeAmount" DECIMAL(12,2),"currencyCode" TEXT NOT NULL DEFAULT 'INR',"notes" TEXT,"createdBy" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "GradeSectionCapacity" ( "id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"schoolId" TEXT NOT NULL,"academicYearId" TEXT NOT NULL,"gradeLevelId" TEXT NOT NULL,"sectionName" TEXT NOT NULL,"capacity" INTEGER NOT NULL CHECK ("capacity">0),"reservedSeats" INTEGER NOT NULL DEFAULT 0 CHECK ("reservedSeats">=0),"enrolledSeats" INTEGER NOT NULL DEFAULT 0 CHECK ("enrolledSeats">=0),CHECK ("reservedSeats" + "enrolledSeats" <= "capacity"),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AdmissionFeeHandoff" ( "id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"schoolId" TEXT NOT NULL,"applicationId" TEXT NOT NULL,"offerId" TEXT,"amount" DECIMAL(12,2) NOT NULL CHECK ("amount">=0),"currencyCode" TEXT NOT NULL DEFAULT 'INR',"status" TEXT NOT NULL DEFAULT 'PENDING',"externalReference" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE UNIQUE INDEX "AdmissionApplication_schoolId_applicationNumber_key" ON "AdmissionApplication"("schoolId","applicationNumber");
CREATE UNIQUE INDEX "AdmissionApplication_id_organizationId_schoolId_key" ON "AdmissionApplication"("id","organizationId","schoolId");
CREATE UNIQUE INDEX "AdmissionOffer_schoolId_offerNumber_key" ON "AdmissionOffer"("schoolId","offerNumber");
CREATE UNIQUE INDEX "GradeSectionCapacity_schoolId_academicYearId_gradeLevelId_sectionName_key" ON "GradeSectionCapacity"("schoolId","academicYearId","gradeLevelId","sectionName");
CREATE INDEX "AdmissionApplication_tenant_status_idx" ON "AdmissionApplication"("organizationId","schoolId","status","createdAt");
CREATE INDEX "AdmissionEnquiry_tenant_status_idx" ON "AdmissionEnquiry"("organizationId","schoolId","status","createdAt");
CREATE INDEX "AdmissionDocument_application_status_idx" ON "AdmissionApplicationDocument"("organizationId","schoolId","applicationId","status");
CREATE INDEX "AdmissionHistory_application_idx" ON "AdmissionStageHistory"("organizationId","schoolId","applicationId","createdAt");
CREATE INDEX "AdmissionOffer_application_idx" ON "AdmissionOffer"("organizationId","schoolId","applicationId","status");
CREATE INDEX "GradeCapacity_tenant_year_grade_idx" ON "GradeSectionCapacity"("organizationId","schoolId","academicYearId","gradeLevelId");
ALTER TABLE "AdmissionApplication" ADD CONSTRAINT "AdmissionApplication_grade_tenant_fk" FOREIGN KEY ("gradeLevelId","organizationId","schoolId") REFERENCES "GradeLevel"("id","organizationId","schoolId");
ALTER TABLE "AdmissionApplication" ADD CONSTRAINT "AdmissionApplication_year_tenant_fk" FOREIGN KEY ("academicYearId","organizationId","schoolId") REFERENCES "AcademicYear"("id","organizationId","schoolId");
ALTER TABLE "GradeSectionCapacity" ADD CONSTRAINT "GradeSectionCapacity_year_tenant_fk" FOREIGN KEY ("academicYearId","organizationId","schoolId") REFERENCES "AcademicYear"("id","organizationId","schoolId");
ALTER TABLE "GradeSectionCapacity" ADD CONSTRAINT "GradeSectionCapacity_grade_tenant_fk" FOREIGN KEY ("gradeLevelId","organizationId","schoolId") REFERENCES "GradeLevel"("id","organizationId","schoolId");
ALTER TABLE "AdmissionApplicationDocument" ADD CONSTRAINT "AdmissionDocument_application_tenant_fk" FOREIGN KEY ("applicationId","organizationId","schoolId") REFERENCES "AdmissionApplication"("id","organizationId","schoolId") ON DELETE CASCADE;
ALTER TABLE "AdmissionStageHistory" ADD CONSTRAINT "AdmissionHistory_application_tenant_fk" FOREIGN KEY ("applicationId","organizationId","schoolId") REFERENCES "AdmissionApplication"("id","organizationId","schoolId") ON DELETE CASCADE;
ALTER TABLE "AdmissionOffer" ADD CONSTRAINT "AdmissionOffer_application_tenant_fk" FOREIGN KEY ("applicationId","organizationId","schoolId") REFERENCES "AdmissionApplication"("id","organizationId","schoolId") ON DELETE CASCADE;
ALTER TABLE "AdmissionFeeHandoff" ADD CONSTRAINT "AdmissionFeeHandoff_application_tenant_fk" FOREIGN KEY ("applicationId","organizationId","schoolId") REFERENCES "AdmissionApplication"("id","organizationId","schoolId") ON DELETE CASCADE;
ALTER TABLE "AdmissionEnquiry" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "AdmissionEnquiry" FORCE ROW LEVEL SECURITY;
CREATE POLICY "AdmissionEnquiry_tenant_policy" ON "AdmissionEnquiry" USING ("organizationId" = current_setting('app.current_organization_id', true) AND "schoolId" = current_setting('app.current_school_id', true)) WITH CHECK ("organizationId" = current_setting('app.current_organization_id', true) AND "schoolId" = current_setting('app.current_school_id', true));
